-- Disposable test database only. Synthetic identities are not production sessions.
create schema private;create schema auth;
do $$begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon;end if;if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated;end if;if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role;end if;end$$;
create table auth.users(id uuid primary key);
create table public.admin_users(user_id uuid primary key);
create function auth.uid() returns uuid language sql as $$select nullif(current_setting('mlg_test.actor',true),'')::uuid$$;
create function public.is_admin() returns boolean language sql as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
create function private.require_admin_aal2_if_enrolled() returns void language sql as $$select$$;
create table public.clubs(id uuid primary key,name text,balance bigint,deleted_at timestamptz,updated_at timestamptz);
create table public.test_commitments(club_id uuid primary key,amount bigint);
create function private.club_financial_commitment(uuid,uuid,uuid,uuid) returns bigint language sql as $$select coalesce((select amount from public.test_commitments where club_id=$1),0)$$;
create table public.players(id uuid primary key,club_id uuid,name text,position text,roster_active boolean default true,market_status text default 'available',deleted_at timestamptz,updated_at timestamptz default clock_timestamp());
create table public.free_agents(id uuid primary key,name text,position text,week_rating text,category text,market_value bigint,acquired_by_club_id uuid,acquired_at timestamptz,status text);
create table public.negotiations(id uuid primary key,type text,club_a_id uuid,club_b_id uuid,player_ids_a jsonb default '[]',player_ids_b jsonb default '[]',cash_from_a bigint default 0,cash_from_b bigint default 0,status text,market_cycle_id uuid,updated_at timestamptz default clock_timestamp());
create table public.transfers(id uuid primary key,source_negotiation_id uuid,player_id uuid,from_club_id uuid,to_club_id uuid,free_agent_id uuid,price bigint,status text,market_cycle_id uuid,deleted_at timestamptz,created_at timestamptz default clock_timestamp());
create table public.market_windows(id uuid default gen_random_uuid(),market_cycle_id uuid,transfer_window_open boolean default true,trade_window_open boolean default true,maintenance_mode boolean default false,read_only_mode boolean default false,updated_at timestamptz default clock_timestamp());
create table public.market_module_policies(module text,rules jsonb default '{}');
create table public.platform_member_access(id boolean,members_released boolean);
create table public.whatsapp_market_inbox(id uuid primary key,revision integer default 1,status text,kind text,transfer_id uuid,negotiation_id uuid,from_club_id uuid,to_club_id uuid,free_agent_id uuid,amount bigint,player_ids_from uuid[] default '{}',player_ids_to uuid[] default '{}',parsed jsonb default '{}',participant_id text,market_cycle_id uuid,settled_at timestamptz,updated_at timestamptz default clock_timestamp());
create table public.transactions(id uuid primary key default gen_random_uuid(),club_id uuid,type text,amount bigint,description text,created_by uuid,balance_after bigint,transaction_type text,archived_at timestamptz,created_at timestamptz default clock_timestamp());
create table public.club_loan_contracts(id uuid,status text,loaned_player_id uuid,collateral_player_id uuid);
create table public.admin_market_worksheet(id uuid,negotiation_id uuid,voided_at timestamptz,voided_by uuid,void_reason text);
create table public.audit_logs(id uuid default gen_random_uuid(),actor_id uuid,action text,target text,details jsonb,before_value jsonb,after_value jsonb);
create table public.notifications(user_id uuid,category text,title text,body text);
create table public.test_reactions(inbox_id uuid,emoji text);
create function private.queue_whatsapp_market_reaction(uuid,text) returns void language sql as $$insert into public.test_reactions values($1,$2)$$;
create function private.market_contract_snapshot(text,uuid) returns jsonb language sql as $$select coalesce((select to_jsonb(n) from public.negotiations n where id=$2),(select to_jsonb(t) from public.transfers t where id=$2))$$;
create function private.whatsapp_market_directory_actor(text) returns jsonb language sql as $$select jsonb_build_object('club_id',(select id from public.clubs order by id limit 1))$$;
create function public.admin_approve_whatsapp_market_without_member_accounts(uuid,integer,boolean,boolean,text) returns jsonb language sql as $$select '{"success":true}'::jsonb$$;
create function public.admin_approve_whatsapp_market_proposal(uuid,integer) returns jsonb language sql as $$select '{"success":true}'::jsonb$$;
